    recovery=[('Mailbox accepted; outbox not marked','Execution retries trusted accept with the same identity.','No duplicate logical message'),('Acknowledgment reply lost','Retry recovers durable acknowledgment after reauthorization.','No resurrection of consumed delivery'),('Full / revoked reply route','Outbox remains pending until a valid retry can succeed.','No dropped completion')],
